import os

def valid_dir(path):
 parts = [p for p in path.split(os.sep) if p]
 for p in parts:
 if p.startswith('.') or p in ('.git', 'pycache', 'node_modules'):
 return False
 return True

results = []
for root, dirs, files in os.walk('.'):
 dirs[:] = [d for d in dirs if not d.startswith('.') and d not in ('.git', 'pycache', 'node_modules')]
 if not valid_dir(root):
 continue
 for f in sorted(files):
 if f.endswith('.py'):
 p = os.path.normpath(os.path.join(root, f))
 try:
 with open(p, 'r', encoding='utf-8', errors='replace') as fh:
 n = sum(1 for _ in fh)
 except Exception:
 n = -1
 results.append((p, n))

results.sort()
total = sum(n for _, n in results if n >= 0)
lines = ['# Python 文件行数统计', '']
for p, n in results:
 if n < 0:
 lines.append('- %s: 读取失败' % p)
 else:
 lines.append('- %s: %d 行' % (p, n))
lines.append('')
lines.append('共 %d 个 .py 文件，总计 %d 行' % (len(results), total))

with open('stats.md', 'w', encoding='utf-8') as f:
 f.write('
'.join(lines) + '
')

print('OK, written stats.md')
for p, n in results:
 print(p, n)
print('total:', total)
